styleCss:
#pomi-lip-tint-blush-learn-page {
  font-family: Arial, Helvetica, sans-serif;
  color: #2b211d;
  background: #fffaf7;
  line-height: 1.6;
}

#pomi-lip-tint-blush-learn-page * {
  box-sizing: border-box;
}

#pomi-lip-tint-blush-learn-page .pomi-wrap {
  width: min(1120px, 92%);
  margin: 0 auto;
}

#pomi-lip-tint-blush-learn-page .pomi-hero {
  padding: 70px 0 50px;
  background:
    radial-gradient(circle at top right, rgba(196, 142, 117, 0.25), transparent 35%),
    linear-gradient(135deg, #fff4ed 0%, #fffaf7 52%, #f3ded2 100%);
  border-radius: 0 0 34px 34px;
}

#pomi-lip-tint-blush-learn-page .pomi-hero-grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 36px;
  align-items: center;
}

#pomi-lip-tint-blush-learn-page .pomi-kicker {
  display: inline-block;
  padding: 8px 14px;
  background: #f1d8cc;
  color: #6e3f31;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  margin-bottom: 18px;
}

#pomi-lip-tint-blush-learn-page h1 {
  font-size: clamp(38px, 5vw, 64px);
  line-height: 1.05;
  margin: 0 0 18px;
  color: #2b211d;
}

#pomi-lip-tint-blush-learn-page h2 {
  font-size: clamp(28px, 4vw, 42px);
  line-height: 1.15;
  margin: 0 0 16px;
  color: #2b211d;
}

#pomi-lip-tint-blush-learn-page h3 {
  font-size: 22px;
  line-height: 1.25;
  margin: 0 0 10px;
  color: #2b211d;
}

#pomi-lip-tint-blush-learn-page p {
  margin: 0 0 16px;
  font-size: 17px;
  color: #4b3c36;
}

#pomi-lip-tint-blush-learn-page ul {
  margin: 0;
  padding-left: 20px;
  color: #4b3c36;
  font-size: 16px;
}

#pomi-lip-tint-blush-learn-page li {
  margin-bottom: 8px;
}

#pomi-lip-tint-blush-learn-page .pomi-lead {
  font-size: 20px;
  max-width: 650px;
  color: #4b3c36;
}

#pomi-lip-tint-blush-learn-page .pomi-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 26px;
}

#pomi-lip-tint-blush-learn-page .pomi-btn {
  display: inline-block;
  padding: 14px 22px;
  border-radius: 999px;
  text-decoration: none;
  font-weight: 700;
  font-size: 16px;
  transition: transform 0.2s ease, opacity 0.2s ease;
}

#pomi-lip-tint-blush-learn-page .pomi-btn:hover {
  transform: translateY(-2px);
  opacity: 0.92;
}

#pomi-lip-tint-blush-learn-page .pomi-btn-primary {
  background: #8f5a47;
  color: #ffffff;
}

#pomi-lip-tint-blush-learn-page .pomi-btn-secondary {
  background: #ffffff;
  color: #8f5a47;
  border: 1px solid #d5b6a8;
}

#pomi-lip-tint-blush-learn-page .pomi-trust {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-top: 34px;
}

#pomi-lip-tint-blush-learn-page .pomi-trust-item {
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid #ecd4c8;
  padding: 16px;
  border-radius: 18px;
  font-weight: 700;
  color: #5b3b31;
}

#pomi-lip-tint-blush-learn-page .pomi-hero-art {
  background: #ffffff;
  border: 1px solid #efd9cf;
  border-radius: 30px;
  padding: 28px;
  box-shadow: 0 18px 45px rgba(74, 50, 40, 0.12);
  min-height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
}

#pomi-lip-tint-blush-learn-page .pomi-lip-card {
  width: 100%;
  max-width: 420px;
  border-radius: 26px;
  background:
    radial-gradient(circle at 50% 42%, rgba(143, 90, 71, 0.16), transparent 34%),
    linear-gradient(135deg, #fff7f2, #f0d7cc);
  padding: 34px;
  text-align: center;
  border: 1px solid #e8cfc3;
}

#pomi-lip-tint-blush-learn-page .pomi-lip-card svg {
  width: 100%;
  max-width: 310px;
  height: auto;
  margin-bottom: 20px;
}

#pomi-lip-tint-blush-learn-page .pomi-lip-card strong {
  display: block;
  font-size: 24px;
  color: #2b211d;
  margin-bottom: 8px;
}

#pomi-lip-tint-blush-learn-page .pomi-lip-card span {
  display: block;
  font-size: 15px;
  color: #5d4a43;
}

#pomi-lip-tint-blush-learn-page .pomi-section {
  padding: 62px 0;
}

#pomi-lip-tint-blush-learn-page .pomi-section-light {
  background: #ffffff;
}

#pomi-lip-tint-blush-learn-page .pomi-two-col {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 36px;
  align-items: start;
}

#pomi-lip-tint-blush-learn-page .pomi-card-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 26px;
}

#pomi-lip-tint-blush-learn-page .pomi-card {
  background: #ffffff;
  border: 1px solid #efd9cf;
  border-radius: 22px;
  padding: 22px;
  box-shadow: 0 10px 28px rgba(74, 50, 40, 0.08);
}

#pomi-lip-tint-blush-learn-page .pomi-card svg {
  width: 34px;
  height: 34px;
  margin-bottom: 14px;
  color: #8f5a47;
}

#pomi-lip-tint-blush-learn-page .pomi-card p {
  font-size: 15px;
  margin-bottom: 0;
}

#pomi-lip-tint-blush-learn-page .pomi-answer-box {
  background: #fff4ed;
  border: 1px solid #efd9cf;
  border-radius: 30px;
  padding: 30px;
  margin-top: 26px;
}

#pomi-lip-tint-blush-learn-page .pomi-compare {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
  margin-top: 26px;
}

#pomi-lip-tint-blush-learn-page .pomi-compare-card {
  background: #ffffff;
  border: 1px solid #efd9cf;
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 10px 28px rgba(74, 50, 40, 0.08);
}

#pomi-lip-tint-blush-learn-page .pomi-process {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
  margin-top: 26px;
}

#pomi-lip-tint-blush-learn-page .pomi-step {
  background: #fffaf7;
  border: 1px solid #efd9cf;
  border-radius: 24px;
  padding: 24px;
}

#pomi-lip-tint-blush-learn-page .pomi-step-number {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: #8f5a47;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  margin-bottom: 16px;
}

#pomi-lip-tint-blush-learn-page .pomi-wide-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
  margin-top: 26px;
}

#pomi-lip-tint-blush-learn-page .pomi-wide-card {
  background: #ffffff;
  border: 1px solid #efd9cf;
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 10px 28px rgba(74, 50, 40, 0.08);
}

#pomi-lip-tint-blush-learn-page .pomi-faq {
  display: grid;
  gap: 14px;
  margin-top: 26px;
}

#pomi-lip-tint-blush-learn-page details {
  background: #ffffff;
  border: 1px solid #efd9cf;
  border-radius: 18px;
  padding: 18px 20px;
}

#pomi-lip-tint-blush-learn-page summary {
  cursor: pointer;
  font-weight: 800;
  color: #2b211d;
  font-size: 18px;
}

#pomi-lip-tint-blush-learn-page details p {
  margin-top: 12px;
  margin-bottom: 0;
}

#pomi-lip-tint-blush-learn-page .pomi-link-box {
  background: #fff4ed;
  border: 1px solid #efd9cf;
  border-radius: 30px;
  padding: 30px;
}

#pomi-lip-tint-blush-learn-page .pomi-note-box {
  background: #fff4ed;
  border: 1px solid #efd9cf;
  border-radius: 30px;
  padding: 30px;
}

#pomi-lip-tint-blush-learn-page .pomi-note-box a {
  color: #8f5a47;
  font-weight: 700;
  text-decoration: underline;
}

#pomi-lip-tint-blush-learn-page .pomi-final {
  text-align: center;
  padding: 70px 0;
  background: #2b211d;
  color: #ffffff;
}

#pomi-lip-tint-blush-learn-page .pomi-final h2,
#pomi-lip-tint-blush-learn-page .pomi-final p {
  color: #ffffff;
}

#pomi-lip-tint-blush-learn-page .pomi-final p {
  max-width: 720px;
  margin-left: auto;
  margin-right: auto;
}

@media (max-width: 900px) {
  #pomi-lip-tint-blush-learn-page .pomi-hero-grid,
  #pomi-lip-tint-blush-learn-page .pomi-two-col,
  #pomi-lip-tint-blush-learn-page .pomi-compare,
  #pomi-lip-tint-blush-learn-page .pomi-wide-grid {
    grid-template-columns: 1fr;
  }

  #pomi-lip-tint-blush-learn-page .pomi-card-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  #pomi-lip-tint-blush-learn-page .pomi-process,
  #pomi-lip-tint-blush-learn-page .pomi-trust {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 560px) {
  #pomi-lip-tint-blush-learn-page .pomi-card-grid {
    grid-template-columns: 1fr;
  }

  #pomi-lip-tint-blush-learn-page .pomi-actions {
    flex-direction: column;
  }

  #pomi-lip-tint-blush-learn-page .pomi-btn {
    text-align: center;
    width: 100%;
  }

  #pomi-lip-tint-blush-learn-page .pomi-hero {
    padding-top: 46px;
  }

  #pomi-lip-tint-blush-learn-page .pomi-hero-art {
    min-height: 280px;
  }
}
